--
-- Name: compute_time_of_day(time without time zone); Type: FUNCTION; Schema: public; Owner: courseflix
--

CREATE FUNCTION public.compute_time_of_day(t time without time zone) RETURNS public.time_of_day_type
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    -- Tune these thresholds as desired
    IF t < TIME '09:00' THEN
        RETURN 'Early AM';
    ELSIF t < TIME '12:00' THEN
        RETURN 'Morning';
    ELSIF t < TIME '17:00' THEN
        RETURN 'Afternoon';
    ELSE
        RETURN 'Evening';
    END IF;
END;
$$;


ALTER FUNCTION public.compute_time_of_day(t time without time zone) OWNER TO courseflix;

--
-- Name: refresh_course_statistics(uuid); Type: FUNCTION; Schema: public; Owner: courseflix
--

CREATE FUNCTION public.refresh_course_statistics(target_course_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
    UPDATE courses
    SET
        review_count = (
            SELECT COUNT(*)
            FROM reviews r
            JOIN course_sections cs ON r.course_section_id = cs.id
            WHERE cs.course_id = target_course_id
        ),
        rating = (
            SELECT ROUND(AVG(r.rating)::numeric, 2)
            FROM reviews r
            JOIN course_sections cs ON r.course_section_id = cs.id
            WHERE cs.course_id = target_course_id
        ),
        avg_hours_per_week = (
            SELECT ROUND(AVG(r.hours_per_week)::numeric, 2)
            FROM reviews r
            JOIN course_sections cs ON r.course_section_id = cs.id
            WHERE cs.course_id = target_course_id
              AND r.hours_per_week IS NOT NULL
        ),
        difficulty_rating = (
            SELECT ROUND(AVG(r.difficulty)::numeric, 2)
            FROM reviews r
            JOIN course_sections cs ON r.course_section_id = cs.id
            WHERE cs.course_id = target_course_id
        ),
        would_take_again_percentage = (
            SELECT ROUND(
                (SUM(CASE WHEN r.would_take_again THEN 1 ELSE 0 END)::numeric
                 / NULLIF(SUM(CASE WHEN r.would_take_again IS NULL THEN 0 ELSE 1 END), 0)) * 100
            , 2)
            FROM reviews r
            JOIN course_sections cs ON r.course_section_id = cs.id
            WHERE cs.course_id = target_course_id
        ),
        updated_at = CURRENT_TIMESTAMP
    WHERE id = target_course_id;
END;
$$;


ALTER FUNCTION public.refresh_course_statistics(target_course_id uuid) OWNER TO courseflix;

--
-- Name: set_meeting_time_of_day(); Type: FUNCTION; Schema: public; Owner: courseflix
--

CREATE FUNCTION public.set_meeting_time_of_day() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.time_of_day = compute_time_of_day(NEW.start_time);
    RETURN NEW;
END;
$$;


ALTER FUNCTION public.set_meeting_time_of_day() OWNER TO courseflix;

--
-- Name: trigger_refresh_course_statistics(); Type: FUNCTION; Schema: public; Owner: courseflix
--

CREATE FUNCTION public.trigger_refresh_course_statistics() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    affected_course_id UUID;
BEGIN
    IF TG_OP = 'DELETE' THEN
        SELECT cs.course_id INTO affected_course_id
        FROM course_sections cs
        WHERE cs.id = OLD.course_section_id;
    ELSE
        SELECT cs.course_id INTO affected_course_id
        FROM course_sections cs
        WHERE cs.id = NEW.course_section_id;
    END IF;

    IF affected_course_id IS NOT NULL THEN
        PERFORM refresh_course_statistics(affected_course_id);
    END IF;

    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION public.trigger_refresh_course_statistics() OWNER TO courseflix;

